"""Affine cipher implementation.

See .docs/instructions.md for the full specification.
"""

from math import gcd

M = 26
GROUP_SIZE = 5


def _check_coprime(a):
    if gcd(a, M) != 1:
        raise ValueError("a and m must be coprime.")


def _modular_inverse(a):
    for x in range(M):
        if (a * x) % M == 1:
            return x
    raise ValueError("a and m must be coprime.")


def encode(plain_text, a, b):
    _check_coprime(a)

    result = []
    for char in plain_text:
        if char.isalpha():
            i = ord(char.lower()) - ord("a")
            result.append(chr((a * i + b) % M + ord("a")))
        elif char.isdigit():
            result.append(char)

    grouped = ["".join(result[i : i + GROUP_SIZE]) for i in range(0, len(result), GROUP_SIZE)]
    return " ".join(grouped)


def decode(ciphered_text, a, b):
    _check_coprime(a)

    a_inv = _modular_inverse(a)

    result = []
    for char in ciphered_text:
        if char.isalpha():
            y = ord(char.lower()) - ord("a")
            result.append(chr((a_inv * (y - b)) % M + ord("a")))
        elif char.isdigit():
            result.append(char)

    return "".join(result)

